import {
  afterEach,
  beforeAll,
  beforeEach,
  vitest,
  type MockInstance,
} from "vitest";
import { p } from "../app/db";
import { createTmpDir } from "~/modules/server-functions/tests/test-utils";
import { rm } from "fs/promises";
import { fs } from "~/fs";

if (!process.env.DATABASE_URL?.includes("localhost")) {
  throw new Error("DATABASE_URL is not targeting localhost");
}

const allTables = [
  "exerciseVideoTake",
  "exercise",
  "section",
  "course",
  "analyticsEvent",
  "socialPostToSocialPostCollection",
  "socialPost",
  "socialPostCollection",
  "contentWorkflowRunStep",
  "contentWorkflowRun",
  "contentWorkflowStep",
  "contentWorkflow",
] as const;

const clearAllTables = async () => {
  await p.$transaction(
    allTables.map((table) => (p[table] as any).deleteMany())
  );
};

beforeAll(async () => {
  await p.$connect();
  await clearAllTables();
});

beforeEach(async () => await clearAllTables());

beforeEach(async () => {
  globalThis.testPaths = {
    exercisePlaygroundPath: (await createTmpDir()).dir,
    postsPlaygroundPath: (await createTmpDir()).dir,
    reposDir: (await createTmpDir()).dir,
  };
});

afterEach(async () => {
  if (globalThis.testPaths) {
    await Promise.all(
      Object.values(globalThis.testPaths).map((path) =>
        rm(path, { recursive: true })
      )
    );
  }
});

let openInVSCodeMock: MockInstance;

beforeEach(() => {
  openInVSCodeMock = vitest.spyOn(fs, "openInVSCode").mockResolvedValue();
});

afterEach(() => {
  openInVSCodeMock.mockRestore();
});

import { describe, expect, it } from "vitest";
import { getExerciseSuffix } from "../get-exercise-suffix";

describe("get-exercise-suffix", () => {
  it.each([
    ["introduction.explainer.ts", "explainer.ts"],
    ["001-something.solution.ts", "solution.ts"],
    ["001-something.solution.1.ts", "solution.1.ts"],
    ["001-something.solution.4.ts", "solution.4.ts"],
    ["001-something.problem.server.ts", "problem.server.ts"],
    ["001-something.problem.ts", "problem.ts"],
    ["001-problem-awesome-thing.problem.ts", "problem.ts"],
    ["001-problem-awesome-thing.problem.server.ts", "problem.server.ts"],
    ["001-problem-awesome-thing.ts", undefined],
  ])("%o should resolve to %o", (input, output) => {
    expect(getExerciseSuffix(input)).toBe(output);
  });
});

import { describe, expect, it, vitest } from "vitest";
import { p } from "../../../db";
import { serverFunctions } from "../server-functions";
import { createTmpDir } from "./test-utils";
import { fs } from "~/fs";

describe("exercises", () => {
  describe("create", () => {
    it("Should let you create an exercise", async () => {
      const course = await serverFunctions.courses.create({
        title: "abc",
      });

      const section = await serverFunctions.sections.create({
        courseId: course.id,
        title: "abc",
      });

      const exercise = await serverFunctions.exercises.create({
        sectionId: section.id,
        title: "abc",
      });

      const sectionInDb = await serverFunctions.sections.get({
        id: section.id,
      });

      expect(sectionInDb.exercises).toMatchObject([
        {
          id: exercise.id,
          title: "abc",
        },
      ]);
    });

    it("Should log it in analytics", async () => {
      const course = await serverFunctions.courses.create({
        title: "abc",
      });

      const section = await serverFunctions.sections.create({
        courseId: course.id,
        title: "abc",
      });

      await serverFunctions.exercises.create({
        sectionId: section.id,
        title: "abc",
      });

      const analytics = await serverFunctions.analytics.allCounts();

      expect(analytics.exercisesCreatedToday).toEqual(1);
    });
  });
  describe("moveSection", async () => {
    it("Should move the exercise from one section to another", async () => {
      const course = await p.course.create({
        data: {
          title: "abc",
          type: "WORKSHOP",
        },
      });

      const section1 = await p.section.create({
        data: {
          courseId: course.id,
          order: 0,
          title: "abc",
        },
      });

      const section2 = await p.section.create({
        data: {
          courseId: course.id,
          order: 0,
          title: "abc",
        },
      });

      const exercise = await p.exercise.create({
        data: {
          order: 0,
          title: "abc",
          sectionId: section1.id,
        },
      });

      await serverFunctions.exercises.moveSection({
        exerciseId: exercise.id,
        sectionId: section2.id,
      });

      expect(
        await p.exercise.findFirstOrThrow({ where: { id: exercise.id } })
      ).toMatchObject({
        id: exercise.id,
        sectionId: section2.id,
      });
    });
  });

  describe("get", () => {
    it("Should return the exercise", async () => {
      const course = await serverFunctions.courses.create({
        title: "abc",
      });

      const section = await serverFunctions.sections.create({
        courseId: course.id,
        title: "abc",
      });

      const exercise = await serverFunctions.exercises.create({
        sectionId: section.id,
        title: "abc",
      });

      expect(
        await serverFunctions.exercises.get({
          id: exercise.id,
        })
      ).toMatchObject({
        id: exercise.id,
        title: "abc",
      });
    });

    it("Should return any associated files", async () => {
      const course = await serverFunctions.courses.create({
        title: "abc",
      });

      const section = await serverFunctions.sections.create({
        courseId: course.id,
        title: "abc",
      });

      const exercise = await serverFunctions.exercises.create({
        sectionId: section.id,
        title: "abc",
      });

      vitest.spyOn(fs, "openInVSCode").mockResolvedValue();

      await serverFunctions.exercises.createExplainerFile({
        id: exercise.id,
      });

      expect(
        await serverFunctions.exercises
          .get({ id: exercise.id })
          .then((exercise) => exercise.files)
      ).toHaveLength(1);
    });
  });

  describe("createExplainerFile", () => {
    it("Should create an explainer file for the exercise", async () => {
      const course = await serverFunctions.courses.create({
        title: "abc",
      });

      const section = await serverFunctions.sections.create({
        courseId: course.id,
        title: "abc",
      });

      const exercise = await serverFunctions.exercises.create({
        sectionId: section.id,
        title: "abc",
      });

      vitest.spyOn(fs, "openInVSCode").mockResolvedValue();

      await serverFunctions.exercises.createExplainerFile({
        id: exercise.id,
      });

      expect(
        await serverFunctions.exercises
          .get({ id: exercise.id })
          .then((exercise) => exercise.files)
      ).toHaveLength(1);
    });

    it("Should throw an error if an explainer file already exists", async () => {
      const course = await serverFunctions.courses.create({
        title: "abc",
      });

      const section = await serverFunctions.sections.create({
        courseId: course.id,
        title: "abc",
      });

      const exercise = await serverFunctions.exercises.create({
        sectionId: section.id,
        title: "abc",
      });

      vitest.spyOn(fs, "openInVSCode").mockResolvedValue();

      await serverFunctions.exercises.createExplainerFile({
        id: exercise.id,
      });

      await expect(
        serverFunctions.exercises.createExplainerFile({
          id: exercise.id,
        })
      ).rejects.toThrow("Explainer file already exists");
    });
  });

  describe("getPrevExercise", () => {
    it("Should return the previous exercise", async () => {
      const course = await serverFunctions.courses.create({
        title: "abc",
      });

      const section = await serverFunctions.sections.create({
        courseId: course.id,
        title: "abc",
      });

      const exercise1 = await serverFunctions.exercises.create({
        sectionId: section.id,
        title: "abc",
      });

      const exercise2 = await serverFunctions.exercises.create({
        sectionId: section.id,
        title: "abc",
      });

      expect(
        await serverFunctions.exercises.getPrevExercise({
          id: exercise2.id,
        })
      ).toMatchObject({
        id: exercise1.id,
      });
    });

    it("Should get the last exercise of the previous section if no previous exercise exists", async () => {
      const course = await serverFunctions.courses.create({
        title: "abc",
      });

      const section1 = await serverFunctions.sections.create({
        courseId: course.id,
        title: "abc",
      });

      const section2 = await serverFunctions.sections.create({
        courseId: course.id,
        title: "abc",
      });

      const exercise1 = await serverFunctions.exercises.create({
        sectionId: section1.id,
        title: "abc",
      });

      const exercise2 = await serverFunctions.exercises.create({
        sectionId: section2.id,
        title: "abc",
      });

      expect(
        await serverFunctions.exercises.getPrevExercise({
          id: exercise2.id,
        })
      ).toMatchObject({
        id: exercise1.id,
      });
    });

    it("Should return null if there is no previous exercise", async () => {
      const course = await serverFunctions.courses.create({
        title: "abc",
      });

      const section = await serverFunctions.sections.create({
        courseId: course.id,
        title: "abc",
      });

      const exercise = await serverFunctions.exercises.create({
        sectionId: section.id,
        title: "abc",
      });

      expect(
        await serverFunctions.exercises.getPrevExercise({
          id: exercise.id,
        })
      ).toBeNull();
    });
  });

  describe("getNextExercise", () => {
    it("Should return the next exercise", async () => {
      const course = await serverFunctions.courses.create({
        title: "abc",
      });

      const section = await serverFunctions.sections.create({
        courseId: course.id,
        title: "abc",
      });

      const exercise1 = await serverFunctions.exercises.create({
        sectionId: section.id,
        title: "abc",
      });

      const exercise2 = await serverFunctions.exercises.create({
        sectionId: section.id,
        title: "abc",
      });

      expect(
        await serverFunctions.exercises.getNextExercise({
          id: exercise1.id,
        })
      ).toMatchObject({
        id: exercise2.id,
      });
    });

    it("Should get the first exercise of the next section if no next exercise exists", async () => {
      const course = await serverFunctions.courses.create({
        title: "abc",
      });

      const section1 = await serverFunctions.sections.create({
        courseId: course.id,
        title: "abc",
      });

      const section2 = await serverFunctions.sections.create({
        courseId: course.id,
        title: "abc",
      });

      const exercise1 = await serverFunctions.exercises.create({
        sectionId: section1.id,
        title: "abc",
      });

      const exercise2 = await serverFunctions.exercises.create({
        sectionId: section2.id,
        title: "abc",
      });

      expect(
        await serverFunctions.exercises.getNextExercise({
          id: exercise1.id,
        })
      ).toMatchObject({
        id: exercise2.id,
      });
    });

    it("Should return null if there is no next exercise", async () => {
      const course = await serverFunctions.courses.create({
        title: "abc",
      });

      const section = await serverFunctions.sections.create({
        courseId: course.id,
        title: "abc",
      });

      const exercise = await serverFunctions.exercises.create({
        sectionId: section.id,
        title: "abc",
      });

      expect(
        await serverFunctions.exercises.getNextExercise({
          id: exercise.id,
        })
      ).toBeNull();
    });
  });
});

import { ConfigProvider, Effect } from "effect";
import { expect, it } from "vitest";
import { LinksStorageService } from "./services.js";
import { mkdtempSync, rmSync, writeFileSync, readFileSync } from "node:fs";
import path from "node:path";
import { NodeFileSystem } from "@effect/platform-node";

it("should get empty array when file does not exist", async () => {
  const tmpdir = mkdtempSync(path.join(import.meta.dirname, "tmp"));
  const linksPath = path.join(tmpdir, "links.json");

  try {
    const links = await Effect.gen(function* () {
      const linksStorage = yield* LinksStorageService;
      return yield* linksStorage.getLinks();
    }).pipe(
      Effect.provide(LinksStorageService.Default),
      Effect.provide(NodeFileSystem.layer),
      Effect.withConfigProvider(
        ConfigProvider.fromJson({
          LINKS_STORAGE_PATH: linksPath,
        })
      ),
      Effect.runPromise
    );

    expect(links).toEqual([]);
  } finally {
    rmSync(tmpdir, { recursive: true });
  }
});

it("should get empty array when file is empty", async () => {
  const tmpdir = mkdtempSync(path.join(import.meta.dirname, "tmp"));
  const linksPath = path.join(tmpdir, "links.json");

  // Create empty file
  writeFileSync(linksPath, "");

  try {
    const links = await Effect.gen(function* () {
      const linksStorage = yield* LinksStorageService;
      return yield* linksStorage.getLinks();
    }).pipe(
      Effect.provide(LinksStorageService.Default),
      Effect.provide(NodeFileSystem.layer),
      Effect.withConfigProvider(
        ConfigProvider.fromJson({
          LINKS_STORAGE_PATH: linksPath,
        })
      ),
      Effect.runPromise
    );

    expect(links).toEqual([]);
  } finally {
    rmSync(tmpdir, { recursive: true });
  }
});

it("should get links from existing JSON file", async () => {
  const tmpdir = mkdtempSync(path.join(import.meta.dirname, "tmp"));
  const linksPath = path.join(tmpdir, "links.json");

  const existingLinks = [
    {
      description: "TypeScript Handbook",
      url: "https://www.typescriptlang.org/docs/",
    },
    { description: "Effect Documentation", url: "https://effect.website/" },
  ];

  // Create file with existing links
  writeFileSync(linksPath, JSON.stringify(existingLinks, null, 2));

  try {
    const links = await Effect.gen(function* () {
      const linksStorage = yield* LinksStorageService;
      return yield* linksStorage.getLinks();
    }).pipe(
      Effect.provide(LinksStorageService.Default),
      Effect.provide(NodeFileSystem.layer),
      Effect.withConfigProvider(
        ConfigProvider.fromJson({
          LINKS_STORAGE_PATH: linksPath,
        })
      ),
      Effect.runPromise
    );

    expect(links).toEqual(existingLinks);
  } finally {
    rmSync(tmpdir, { recursive: true });
  }
});

it("should add links to existing storage", async () => {
  const tmpdir = mkdtempSync(path.join(import.meta.dirname, "tmp"));
  const linksPath = path.join(tmpdir, "links.json");

  const existingLinks = [
    {
      description: "TypeScript Handbook",
      url: "https://www.typescriptlang.org/docs/",
    },
  ];

  // Create initial file
  writeFileSync(linksPath, JSON.stringify(existingLinks, null, 2));

  const newLinks = [
    { description: "Effect Documentation", url: "https://effect.website/" },
    { description: "Node.js Docs", url: "https://nodejs.org/docs/" },
  ];

  try {
    await Effect.gen(function* () {
      const linksStorage = yield* LinksStorageService;
      yield* linksStorage.addLinks(newLinks);
    }).pipe(
      Effect.provide(LinksStorageService.Default),
      Effect.provide(NodeFileSystem.layer),
      Effect.withConfigProvider(
        ConfigProvider.fromJson({
          LINKS_STORAGE_PATH: linksPath,
        })
      ),
      Effect.runPromise
    );

    // Read the file to verify it was updated
    const updatedContent = JSON.parse(readFileSync(linksPath, "utf-8"));
    const expectedLinks = [...existingLinks, ...newLinks];

    expect(updatedContent).toEqual(expectedLinks);
  } finally {
    rmSync(tmpdir, { recursive: true });
  }
});

it("should create file and add links when file does not exist", async () => {
  const tmpdir = mkdtempSync(path.join(import.meta.dirname, "tmp"));
  const linksPath = path.join(tmpdir, "links.json");

  const newLinks = [
    {
      description: "TypeScript Handbook",
      url: "https://www.typescriptlang.org/docs/",
    },
    { description: "Effect Documentation", url: "https://effect.website/" },
  ];

  try {
    await Effect.gen(function* () {
      const linksStorage = yield* LinksStorageService;
      yield* linksStorage.addLinks(newLinks);
    }).pipe(
      Effect.provide(LinksStorageService.Default),
      Effect.provide(NodeFileSystem.layer),
      Effect.withConfigProvider(
        ConfigProvider.fromJson({
          LINKS_STORAGE_PATH: linksPath,
        })
      ),
      Effect.runPromise
    );

    // Read the file to verify it was created
    const updatedContent = JSON.parse(readFileSync(linksPath, "utf-8"));
    expect(updatedContent).toEqual(newLinks);
  } finally {
    rmSync(tmpdir, { recursive: true });
  }
});

it("should handle invalid JSON gracefully", async () => {
  const tmpdir = mkdtempSync(path.join(import.meta.dirname, "tmp"));
  const linksPath = path.join(tmpdir, "links.json");

  // Create file with invalid JSON
  writeFileSync(linksPath, "invalid json content");

  try {
    const links = await Effect.gen(function* () {
      const linksStorage = yield* LinksStorageService;
      return yield* linksStorage.getLinks();
    }).pipe(
      Effect.provide(LinksStorageService.Default),
      Effect.provide(NodeFileSystem.layer),
      Effect.withConfigProvider(
        ConfigProvider.fromJson({
          LINKS_STORAGE_PATH: linksPath,
        })
      ),
      Effect.runPromise
    );

    expect(links).toEqual([]);
  } finally {
    rmSync(tmpdir, { recursive: true });
  }
});

it("should get links after adding them", async () => {
  const tmpdir = mkdtempSync(path.join(import.meta.dirname, "tmp"));
  const linksPath = path.join(tmpdir, "links.json");

  const links = [
    {
      description: "TypeScript Handbook",
      url: "https://www.typescriptlang.org/docs/",
    },
    { description: "Effect Documentation", url: "https://effect.website/" },
  ];

  try {
    // First add links
    await Effect.gen(function* () {
      const linksStorage = yield* LinksStorageService;
      yield* linksStorage.addLinks(links);
    }).pipe(
      Effect.provide(LinksStorageService.Default),
      Effect.provide(NodeFileSystem.layer),
      Effect.withConfigProvider(
        ConfigProvider.fromJson({
          LINKS_STORAGE_PATH: linksPath,
        })
      ),
      Effect.runPromise
    );

    // Then get links
    const retrievedLinks = await Effect.gen(function* () {
      const linksStorage = yield* LinksStorageService;
      return yield* linksStorage.getLinks();
    }).pipe(
      Effect.provide(LinksStorageService.Default),
      Effect.provide(NodeFileSystem.layer),
      Effect.withConfigProvider(
        ConfigProvider.fromJson({
          LINKS_STORAGE_PATH: linksPath,
        })
      ),
      Effect.runPromise
    );

    expect(retrievedLinks).toEqual(links);
  } finally {
    rmSync(tmpdir, { recursive: true });
  }
});

